insert into public.topik_question_options(question_id,position,text_ko,is_correct) select id,4,'물어보지 않아도',true from public.topik_questions where source_key='q34-practice-10' on conflict(question_id,position) do update set text_ko=excluded.text_ko,is_correct=excluded.is_correct;
