-- TOPIK II Reading Questions 1-4: schema + normalized seed
-- Source: Chinh phục TOPIK 3-4, tái bản XI, Reading pp. 4-29; answer key p. 309.
-- Generated 2026-09-26. Idempotent: safe to run again.
begin;
create extension if not exists pgcrypto;

create table if not exists public.topik_sources (
 id uuid primary key default gen_random_uuid(), source_key text not null unique,
 title text not null, edition text, scope text, notes text, created_at timestamptz not null default now()
);
create table if not exists public.topik_grammar (
 id uuid primary key default gen_random_uuid(), slug text not null unique, pattern_ko text not null,
 form_rule text, display_meaning_vi text not null, primary_category text not null,
 question_scope text not null check (question_scope in ('Q1_2','Q3_4','BOTH')),
 status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED')),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.topik_grammar_senses (
 id uuid primary key default gen_random_uuid(), grammar_id uuid not null references public.topik_grammar(id) on delete cascade,
 sense_key text not null unique, meaning_vi text not null, usage_note_vi text, constraints_vi text,
 category text not null, status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED'))
);
create table if not exists public.topik_examples (
 id uuid primary key default gen_random_uuid(), sense_id uuid not null references public.topik_grammar_senses(id) on delete cascade,
 sentence_ko text not null, translation_vi text, source_id uuid references public.topik_sources(id),
 source_page_printed text, source_item text, origin text not null check (origin in ('BOOK','ORIGINAL')),
 status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED')),
 unique (sense_id, sentence_ko)
);
create table if not exists public.topik_grammar_relations (
 id uuid primary key default gen_random_uuid(), left_sense_id uuid not null references public.topik_grammar_senses(id) on delete cascade,
 right_sense_id uuid not null references public.topik_grammar_senses(id) on delete cascade,
 relation_type text not null default 'SIMILAR_IN_CONTEXT', context_note_vi text not null,
 source_id uuid references public.topik_sources(id), source_page_printed text, source_item text,
 status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED')),
 check (left_sense_id <> right_sense_id), unique (left_sense_id, right_sense_id, relation_type)
);
create table if not exists public.topik_grammar_relation_groups (
 id uuid primary key default gen_random_uuid(), group_key text not null unique,
 title_vi text not null, category text not null,
 context_note_vi text not null, source_id uuid references public.topik_sources(id),
 source_page_printed text, source_item text,
 status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED'))
);
create table if not exists public.topik_grammar_relation_group_members (
 group_id uuid not null references public.topik_grammar_relation_groups(id) on delete cascade,
 sense_id uuid not null references public.topik_grammar_senses(id) on delete cascade,
 member_order smallint not null check (member_order > 0),
 member_role text not null check (member_role in ('HEAD','EQUIVALENT')),
 primary key(group_id, sense_id), unique(group_id, member_order)
);
create table if not exists public.topik_questions (
 id uuid primary key default gen_random_uuid(), source_key text not null unique,
 kind text not null check (kind in ('FILL_GRAMMAR','SIMILAR_GRAMMAR')), stem_ko text not null,
 target_text text, explanation_vi text not null, source_id uuid references public.topik_sources(id),
 source_page_printed text, source_section text not null, source_item text not null,
 status text not null default 'PUBLISHED' check (status in ('DRAFT','REVIEWED','PUBLISHED'))
);
create table if not exists public.topik_question_options (
 id uuid primary key default gen_random_uuid(), question_id uuid not null references public.topik_questions(id) on delete cascade,
 position smallint not null check (position between 1 and 4), text_ko text not null,
 grammar_sense_id uuid references public.topik_grammar_senses(id), is_correct boolean not null default false,
 why_wrong_vi text, unique(question_id, position)
);
create table if not exists public.topik_question_attempts (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 question_id uuid not null references public.topik_questions(id) on delete cascade,
 selected_option_id uuid references public.topik_question_options(id) on delete set null,
 is_correct boolean not null, mode text not null check (mode in ('FILL','SIMILAR','SPRINT','WRONG_RETRY')),
 answered_at timestamptz not null default now(), duration_ms integer check (duration_ms is null or duration_ms >= 0)
);
create index if not exists idx_topik_grammar_scope on public.topik_grammar(question_scope, primary_category, status);
create index if not exists idx_topik_questions_kind on public.topik_questions(kind, status);
create index if not exists idx_topik_options_question on public.topik_question_options(question_id, position);
create index if not exists idx_topik_attempts_user_question on public.topik_question_attempts(user_id, question_id, answered_at desc);
create index if not exists idx_topik_relation_groups_category on public.topik_grammar_relation_groups(category, status);
create index if not exists idx_topik_relation_members_sense on public.topik_grammar_relation_group_members(sense_id);

on conflict(source_key) do update set title=excluded.title,edition=excluded.edition,scope=excluded.scope,notes=excluded.notes;
update public.topik_grammar set question_scope='BOTH' where slug='g-0693a48190ff61ca';
update public.topik_grammar set question_scope='BOTH' where slug='g-97deeaa8d652737c';
update public.topik_grammar set question_scope='BOTH' where slug='g-d44c2f03688b47d4';
update public.topik_grammar set question_scope='BOTH' where slug='g-7955fec668f5d9f0';
update public.topik_grammar set question_scope='BOTH' where slug='g-8205435be416c95e';
update public.topik_grammar set question_scope='BOTH' where slug='g-4b8937c6691e3127';
update public.topik_grammar set question_scope='BOTH' where slug='g-3289418a85e589ab';
update public.topik_grammar set question_scope='BOTH' where slug='g-7d65d1049414aa02';
update public.topik_grammar set question_scope='BOTH' where slug='g-2e71da5629be0176';
update public.topik_grammar set question_scope='BOTH' where slug='g-7fea59b454ff81bf';
update public.topik_grammar set question_scope='BOTH' where slug='g-639516718fc29f90';
update public.topik_grammar set question_scope='BOTH' where slug='g-f02f2df97e6e4d5a';
update public.topik_grammar set question_scope='BOTH' where slug='g-7a79d1a0b179c365';
update public.topik_grammar set question_scope='BOTH' where slug='g-db438897a9adb4ee';
update public.topik_grammar set question_scope='BOTH' where slug='g-58dd04f57731a7ba';
update public.topik_grammar set question_scope='BOTH' where slug='g-fd7a8b05d339a3ad';
update public.topik_grammar set question_scope='BOTH' where slug='g-9187c157b2cfe661';
update public.topik_grammar set question_scope='BOTH' where slug='g-71f74e26f1d68931';
update public.topik_grammar set question_scope='BOTH' where slug='g-46d3b642f0be712c';
update public.topik_grammar set question_scope='BOTH' where slug='g-e182c72917a33902';
update public.topik_grammar set question_scope='BOTH' where slug='g-381cf23a3b098e86';

-- Published questions must have exactly four options and one correct option.
do $$
declare bad_count integer;
begin
 select count(*) into bad_count from (
   select q.id from public.topik_questions q left join public.topik_question_options o on o.question_id=q.id
   where q.source_id=(select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4') and q.status='PUBLISHED'
   group by q.id having count(o.id)<>4 or count(o.id) filter(where o.is_correct)<>1
 ) bad;
 if bad_count>0 then raise exception 'TOPIK seed validation failed: % invalid published questions',bad_count; end if;
end $$;

-- Verify the published catalog and the multi-member similar-grammar groups.
do $$
declare
 fill_count integer;
 similar_count integer;
 question_count integer;
 option_count integer;
 group_count integer;
 member_count integer;
 invalid_group_count integer;
begin
 select count(*) into fill_count from public.topik_questions
 where source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and kind = 'FILL_GRAMMAR' and status = 'PUBLISHED';
 select count(*) into similar_count from public.topik_questions
 where source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and kind = 'SIMILAR_GRAMMAR' and status = 'PUBLISHED';
 select count(*) into question_count from public.topik_questions
 where source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and status = 'PUBLISHED';
 select count(*) into option_count from public.topik_question_options o
 join public.topik_questions q on q.id = o.question_id
 where q.source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and q.status = 'PUBLISHED';
 select count(*) into group_count from public.topik_grammar_relation_groups
 where source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and status = 'PUBLISHED';
 select count(*) into member_count from public.topik_grammar_relation_group_members members
 join public.topik_grammar_relation_groups groups on groups.id = members.group_id
 where groups.source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
   and groups.status = 'PUBLISHED';
 select count(*) into invalid_group_count from (
   select groups.id from public.topik_grammar_relation_groups groups
   join public.topik_grammar_relation_group_members members on members.group_id = groups.id
   where groups.source_id = (select id from public.topik_sources where source_key='topik-3-4-b11-reading-q1-4')
     and groups.status = 'PUBLISHED'
   group by groups.id
   having count(*) not between 2 and 5
 ) invalid_groups;
 if fill_count <> 24 or similar_count <> 14 or question_count <> 38 or option_count <> 152
    or group_count <> 39 or member_count <> 99 or invalid_group_count <> 0 then
   raise exception 'TOPIK seed counts failed: fill %, similar %, questions %, options %, groups %, members %, invalid groups %',
     fill_count, similar_count, question_count, option_count, group_count, member_count, invalid_group_count;
 end if;
end $$;

alter table public.topik_sources enable row level security;
alter table public.topik_grammar enable row level security;
alter table public.topik_grammar_senses enable row level security;
alter table public.topik_examples enable row level security;
alter table public.topik_grammar_relations enable row level security;
alter table public.topik_grammar_relation_groups enable row level security;
alter table public.topik_grammar_relation_group_members enable row level security;
alter table public.topik_questions enable row level security;
alter table public.topik_question_options enable row level security;
alter table public.topik_question_attempts enable row level security;

do $$ begin
 create policy "read published topik sources" on public.topik_sources for select to authenticated using (true);
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik grammar" on public.topik_grammar for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik senses" on public.topik_grammar_senses for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik examples" on public.topik_examples for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik relations" on public.topik_grammar_relations for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik relation groups" on public.topik_grammar_relation_groups for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read members of published topik groups" on public.topik_grammar_relation_group_members for select to authenticated using (exists(select 1 from public.topik_grammar_relation_groups g where g.id=group_id and g.status='PUBLISHED'));
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read published topik questions" on public.topik_questions for select to authenticated using (status='PUBLISHED');
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "read options of published questions" on public.topik_question_options for select to authenticated using (exists(select 1 from public.topik_questions q where q.id=question_id and q.status='PUBLISHED'));
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "users read own topik attempts" on public.topik_question_attempts for select to authenticated using (auth.uid()=user_id);
exception when duplicate_object then null; end $$;
do $$ begin
 create policy "users insert own topik attempts" on public.topik_question_attempts for insert to authenticated with check (auth.uid()=user_id);
exception when duplicate_object then null; end $$;

commit;

-- Expected after import:
-- 38 questions = 24 Q1-2 + 14 Q3-4; 152 options; 50 Q1-2 grammar entries;
-- 39 Q3-4 relation groups with 2-5 members per group. Pair relations are retained for compatibility.
